languages.javascript:
if (!values.length) throw new Error('Average needs at least one value');
let total = 0;
for (const value of values) total += value;
return total / values.length;

languages.python:
if not values:
    raise ValueError("Average needs at least one value")
total = 0.0
for value in values:
    total += value
return total / len(values)

languages.csharp:
if (values.Count == 0) throw new InvalidOperationException("Average needs at least one value");
var total = 0.0;
foreach (var value in values) total += value;
return total / values.Count;

languages.cpp:
if (values.empty()) throw std::invalid_argument("Average needs at least one value");
double total = 0;
for (double value : values) total += value;
return total / static_cast<double>(values.size());

languages.rust:
if values.is_empty() { panic!("Average needs at least one value"); }
let mut total = 0.0;
for value in values.iter() { total += *value; }
return total / values.len() as f64;

languages.java:
if (values.isEmpty()) throw new IllegalArgumentException("Average needs at least one value");
double total = 0;
for (double value : values) total += value;
return total / values.size();

languages.go:
if len(*values) == 0 {
	VgFail("Average needs at least one value")
}
total := 0.0
for _, value := range *values {
	total += value
}
return total / float64(len(*values))
